#include <stdio.h>

int main(void) {
    const int PIN = 1234;
    double balance = 2500.0;
    int entered, choice;
    double amount;

    printf("=== Open Bank ATM ===\n");
    printf("Enter your PIN: ");
    if (scanf("%d", &entered) != 1 || entered != PIN) {
        printf("Incorrect PIN. Card retained.\n");
        return 1;
    }

    while (1) {
        printf("\n1) Balance  2) Withdraw  3) Deposit  4) Exit\n> ");
        if (scanf("%d", &choice) != 1) break;

        if (choice == 1) {
            printf("Balance: %.2f\n", balance);
        } else if (choice == 2) {
            printf("Amount: ");
            scanf("%lf", &amount);
            if (amount <= 0) printf("Amount must be positive.\n");
            else if (amount > balance) printf("Insufficient funds.\n");
            else if (amount > 1000) printf("Daily limit is 1000.\n");
            else { balance -= amount; printf("Dispensed %.2f. Balance %.2f\n", amount, balance); }
        } else if (choice == 3) {
            printf("Amount: ");
            scanf("%lf", &amount);
            if (amount <= 0) printf("Amount must be positive.\n");
            else { balance += amount; printf("Deposited %.2f. Balance %.2f\n", amount, balance); }
        } else if (choice == 4) {
            printf("Thank you. Please take your card.\n");
            break;
        } else {
            printf("Unknown option.\n");
        }
    }
    return 0;
}

#include <stdio.h>
#include <string.h>

typedef struct { char name[24]; int marks[3]; } Student;

int main(void) {
    Student class[] = {
        {"Asha",   {91, 86, 78}},
        {"Rahul",  {74, 80, 69}},
        {"Meera",  {88, 79, 95}},
        {"Vikram", {55, 62, 48}},
    };
    int n = sizeof class / sizeof class[0];

    printf("%-10s %5s %5s %5s %8s %6s\n", "NAME", "DSA", "OS", "DBMS", "AVERAGE", "GRADE");
    printf("--------------------------------------------------\n");

    double best = -1; const char *topper = "";
    int passed = 0;

    for (int i = 0; i < n; i++) {
        int total = 0;
        for (int j = 0; j < 3; j++) total += class[i].marks[j];
        double avg = total / 3.0;

        char grade = avg >= 85 ? 'A' : avg >= 70 ? 'B' : avg >= 60 ? 'C' : 'F';
        if (grade != 'F') passed++;
        if (avg > best) { best = avg; topper = class[i].name; }

        printf("%-10s %5d %5d %5d %8.2f %6c\n",
               class[i].name, class[i].marks[0], class[i].marks[1], class[i].marks[2], avg, grade);
    }

    printf("--------------------------------------------------\n");
    printf("Topper : %s (%.2f)\n", topper, best);
    printf("Passed : %d of %d (%.0f%%)\n", passed, n, 100.0 * passed / n);
    return 0;
}

class TodoList {
  #items = [];
  #nextId = 1;

  add(text, dueInDays, priority = 'normal') {
    const due = new Date(2026, 0, 1);
    due.setDate(due.getDate() + dueInDays);
    this.#items.push({ id: this.#nextId++, text, due, priority, done: false });
    return this;
  }

  complete(id) {
    const item = this.#items.find((t) => t.id === id);
    if (item) item.done = true;
    return this;
  }

  get pending() {
    const order = { high: 0, normal: 1, low: 2 };
    return this.#items
      .filter((t) => !t.done)
      .sort((a, b) => a.due - b.due || order[a.priority] - order[b.priority]);
  }

  get summary() {
    const done = this.#items.filter((t) => t.done).length;
    return `${done} of ${this.#items.length} done`;
  }
}

